<script setup lang="ts">import {onMounted,ref} from 'vue';const data=ref<any>({}),nodes=ref<any[]>([]),services=ref<any[]>([]);onMounted(async()=>{data.value=await (await fetch('/api/v1/infrastructure')).json();if(data.value.swarm?.active){nodes.value=await (await fetch('/api/v1/infrastructure/nodes')).json();services.value=await (await fetch('/api/v1/infrastructure/services')).json()}})</script><template><div class="hero"><div><p class="kicker">OBSERVABILITY</p><h1>Infrastructure</h1><p class="muted">A clear view of the host running StackHost.</p></div></div><div class="status"><span class="dot"></span><div><strong>{{data.available?'Docker engine connected':'Docker engine unavailable'}}</strong><p>{{data.available?`Docker ${data.engine_version} · ${data.running}/${data.containers} containers running`:data.message||'Docker connection needs attention'}}</p></div><span class="pill">{{data.available?'Available':'Unavailable'}}</span></div><div class="empty"><h2>{{data.swarm?.active?'Swarm cluster':'Swarm is not initialized'}}</h2><p>{{data.swarm?.active?`${data.swarm.nodes} nodes · ${data.swarm.services} services`:'When Docker Swarm is available, nodes and services will appear here.'}}</p></div><div v-if="nodes.length||services.length" class="grid"><article><span class="label">NODES</span><strong>{{nodes.length}}</strong><p class="muted">{{nodes.map(n=>`${n.hostname} · ${n.role}`).join(', ')}}</p></article><article><span class="label">SERVICES</span><strong>{{services.length}}</strong><p class="muted">{{services.map(s=>s.name).join(', ')}}</p></article></div></template>
